            let pendulumEndX = pendulumLength * Math.sin(angle);
            let pendulumEndY = -pendulumLength * Math.cos(angle);
            ctx.beginPath();
            ctx.moveTo(canvas.width / 2, canvas.height / 2);
            ctx.lineTo(canvas.width / 2 + pendulumEndX, canvas.height / 2 + pendulumEndY);
            ctx.stroke();
        }

